import { test } from "node:test";
import assert from "node:assert/strict";
import { mkdirSync, mkdtempSync, rmSync, symlinkSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import path from "node:path";
import {
  classifyAiPolicy, cloneEnv, detectAiTrailer, detectProfile, detectsCla, detectsDco, outOfScopePaths, profilePromptNotes, refuseIssue, setupKey, setupPlan,
} from "../contrib-profile";

test("classifyAiPolicy: bans, disclosure requirements, and silence", () => {
  const bans = [
    "We do not accept contributions generated by AI tools or LLMs.",
    "AI-generated pull requests will be closed without review.".replace("will be closed without review", "are not accepted"),
    "This project prohibits AI-generated code in any form.",
    "Contributions written by ChatGPT, Copilot or similar are not allowed.",
  ];
  for (const text of bans) assert.equal(classifyAiPolicy(text).stance, "ban", text);
  const disclose = [
    "Disclose in PR: Always mention when a pull request includes AI-generated code.",
    "- [ ] AI assistance was used during the creation of this PR.",
    "If you used an LLM, you must state this in the PR description.",
    "- **All AI usage in any form must be disclosed.** You must state",
  ];
  // Ghostty's AI_POLICY.md: a disclosure rule outranks the welcome further down.
  assert.equal(classifyAiPolicy("- **All AI usage in any form must be disclosed.**\n\nAs a project, we welcome AI as a tool!").stance, "disclose");
  for (const text of disclose) assert.equal(classifyAiPolicy(text).stance, "disclose", text);
  // Real policies: Pydantic welcomes AI on conditions; Pallets (Flask) closes AI PRs on sight.
  const pydantic = "## AI policy\n\nWe welcome the use of AI when contributing to Pydantic. However, users should certify that they fully understand the code being submitted.";
  assert.deepEqual(classifyAiPolicy(pydantic), { stance: "welcome", excerpt: "We welcome the use of AI when contributing to Pydantic." });
  for (const text of ["AI-assisted contributions are welcome.", "You may use AI tools, but review the output.",
    // pyjanitor #1714, a maintainer: agents count as AI only after "your"/"coding".
    "Totally ok to use your agents to do it", "It's fine to use coding agents here.", "Feel free to use Copilot."]) assert.equal(classifyAiPolicy(text).stance, "welcome", text);
  for (const text of ["Fine to use the agent class.", "OK to use user agents in tests."]) assert.equal(classifyAiPolicy(text).stance, "unknown", text);
  assert.equal(classifyAiPolicy("AI-generated PRs and issues are closed on sight, without review or discussion.").stance, "ban");
  // A ban anywhere outranks a welcome elsewhere in the same text.
  assert.equal(classifyAiPolicy("We welcome the use of AI for docs.\nAI-generated code is not accepted.").stance, "ban");
  for (const text of ["Please add tests.", "We use a CLA bot.", "Pure code-agent PRs are not allowed. A human must review."]) {
    assert.notEqual(classifyAiPolicy(text).stance, "ban", text);
  }
  assert.match(classifyAiPolicy("Intro.\nWe do not accept AI-generated patches. Thanks.").excerpt!, /^We do not accept AI-generated patches\./);
});

test("classifyAiPolicy: a rule against AI co-author trailers is not a ban (requests' AI_POLICY.md)", () => {
  const requests = [
    "- Every contribution has to be backed by a human who unequivocally owns the copyright for all changes.",
    "  No LLM bots in `Co-authored-by:`s.",
    "",
    "- Pull requests that have an LLM product listed as co-author can't be merged and will be closed without further discussion.",
    "  We cannot risk the copyright status of this project.",
    "",
    "  If you used LLM tools during development, you may still submit – but you must remove any LLM co-author tags and take full ownership of every line.",
  ].join("\n");
  assert.deepEqual(classifyAiPolicy(requests), { stance: "welcome", excerpt: "If you used LLM tools during development, you may still submit – but you must remove any LLM co-author tags and take full ownership of every line." });
  assert.equal(classifyAiPolicy("PRs listing an AI as co-author will be closed.").stance, "unknown", "about the trailer only");
  // A real ban after a co-author rule is still found.
  assert.equal(classifyAiPolicy("PRs listing an AI as co-author will be closed.\nWe do not accept AI-generated code.").stance, "ban");
});

test("classifyAiPolicy: a rule against AI with no human involved welcomes a human's AI-assisted work (fastify, yargs)", () => {
  const fastify = "1. Pure-AI contributions with no human in the loop are not welcome. Pull\nrequests ***MUST*** be opened by a human.";
  assert.deepEqual(classifyAiPolicy(fastify), { stance: "welcome", excerpt: "Pure-AI contributions with no human in the loop are not welcome." });
  assert.deepEqual(classifyAiPolicy("# AI Policy\n\nAI assistance is ok, but there must be a human involved and contributing.\n"),
    { stance: "welcome", excerpt: "AI assistance is ok, but there must be a human involved and contributing." });
  // A real ban beside it still wins, and a stated disclosure rule outranks the welcome.
  assert.equal(classifyAiPolicy(`${fastify}\nWe do not accept AI-generated code.`).stance, "ban");
  assert.equal(classifyAiPolicy(`${fastify}\nAll AI usage must be disclosed.`).stance, "disclose");
});

test("classifyAiPolicy: hard-wrapped policies are read a sentence at a time (Node, Home Assistant, ansible)", () => {
  // Node's AGENTS.md wraps its rule over three lines; the condition is on the last one.
  const node = "* **No unreviewed automation**: Automated pull requests must not be created without\n  ongoing human oversight. The AI agent is not permitted to create pull\n  requests, open issues, post comments, respond to reviews, or push commits without\n  ongoing human oversight.\n\n* A single `Assisted-by: <agent-name>` annotation is required disclosure, not promotion, and is\n  permitted.";
  assert.equal(classifyAiPolicy(node).stance, "disclose");
  assert.equal(classifyAiPolicy(node.split("\n\n")[0]!).stance, "welcome", "the rule alone is about oversight, not a ban");
  const ha = "We support using AI (i.e., LLMs) as tools when contributing to Open Home Foundation projects.\n\nPull requests that appear to be unreviewed AI output will be closed without review.";
  assert.deepEqual(classifyAiPolicy(ha), { stance: "welcome", excerpt: "We support using AI (i.e., LLMs) as tools when contributing to Open Home Foundation projects." });
  assert.equal(classifyAiPolicy("**Note:** This file is for AI assistant use only.").stance, "unknown", "a Note: heading isn't a disclosure rule");
  assert.equal(classifyAiPolicy("Please note in the PR whether you used AI.").stance, "disclose");
  // neovim points at its policy section; the pointer isn't a ban.
  assert.notEqual(classifyAiPolicy("Before sending a PR, read [AI-assisted work](#ai-assisted-work), otherwise your PR will be closed and you may be blocked from the org.").stance, "ban");
  // ripgrep names its AI Policy in CONTRIBUTING.md; the policy itself welcomes AI.
  assert.equal(classifyAiPolicy("All use of AI in contributions must follow the\n[AI Policy](https://example.com/AI_POLICY.md).\n\nContributions not following the AI Policy will be closed.").stance, "unknown");
  assert.equal(classifyAiPolicy("Using AI (i.e., LLMs) as tools for coding is welcome. A high bar is held.").stance, "welcome");
  // prettier: closing low-quality AI content is a condition, not a ban.
  assert.equal(classifyAiPolicy("- Only submit code you fully understand and have tested.\n- Low-quality AI content will be closed immediately.").stance, "welcome");
  assert.equal(classifyAiPolicy("## Note on use of AI, agents and bots ##\n\nGetting help is fine.").stance, "unknown", "a heading isn't a disclosure rule");
  assert.equal(classifyAiPolicy("- Add a brief disclaimer noting AI-agent involvement in the contribution.").stance, "disclose", "LangChain");
  assert.equal(classifyAiPolicy("#### AI Assistance Disclosure (REQUIRED)\n<!-- Select exactly ONE of the following: -->").stance, "disclose", "Django");
  // sqlalchemy bans trolls, AI or not.
  assert.notEqual(classifyAiPolicy("In particular, **users who post content that appears to be trolling for karma /\nupvotes / vanity commits / positive responses, whether or not this content is\nmachine generated, will be banned**.").stance, "ban");
  // A list item ends a sentence; a ban in one item isn't softened by the next.
  assert.equal(classifyAiPolicy("- AI-generated code is not accepted\n- Changes without human review are rejected").stance, "ban");
});

test("DCO, CLA and trailer detection", () => {
  assert.ok(detectsDco("Commits must include a `Signed-off-by:` header"));
  assert.ok(detectsDco("we follow the Developer Certificate of Origin"));
  assert.ok(!detectsDco("Please sign your work emotionally."));
  assert.ok(detectsCla("You must sign the Contributor License Agreement"));
  assert.ok(!detectsCla("clarity matters"));
  assert.equal(detectAiTrailer("Co-authored-by: Claude\n(other projects use Assisted-by: or Generated-by:)"), "Assisted-by");
  assert.equal(detectAiTrailer("Co-authored-by: GitHub Copilot"), "Co-authored-by");
  assert.equal(detectAiTrailer("Co-authored-by: Jane <j@x>"), null);
});

function fixture(files: Record<string, string>): string {
  const dir = mkdtempSync(path.join(tmpdir(), "opensrcer-profile-"));
  for (const [rel, text] of Object.entries(files)) {
    mkdirSync(path.dirname(path.join(dir, rel)), { recursive: true });
    writeFileSync(path.join(dir, rel), text);
  }
  return dir;
}

test("detectProfile reads the repository's own files", () => {
  const dir = fixture({
    "docs/contributing/README.md": "### DCO\nCommits must include a `Signed-off-by:` header.\nAlways mention when a pull request includes AI-generated code. Use Assisted-by: trailers.",
    ".github/PULL_REQUEST_TEMPLATE.md": "## Summary\n\n## How did you test this change?\n",
    "AGENTS.md": "Run the duplicate checks first.",
  });
  try {
    const p = detectProfile(dir, "someone/thing");
    assert.equal(p.dco, true);
    assert.equal(p.cla, null);
    assert.match(p.prTemplate!, /How did you test/);
    assert.match(p.agentInstructions!, /duplicate checks/);
    assert.equal(p.aiPolicy.stance, "disclose");
    assert.equal(p.aiPolicy.source, "docs/contributing/README.md");
    assert.equal(p.aiTrailer, "Assisted-by");
    const notes = profilePromptNotes(p);
    assert.match(notes, /<pr-template untrusted="true">/);
    assert.match(notes, /<agent-instructions untrusted="true">/);
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
});

test("detectProfile: a ban anywhere wins, and symlinked docs are never read", () => {
  const outside = fixture({ "secret.txt": "PRIVATE KEY: we do not accept AI-generated code" });
  const dir = fixture({ "CONTRIBUTING.md": "Mention AI use in the PR.", "AI_POLICY.md": "We do not accept AI-generated contributions." });
  try {
    assert.equal(detectProfile(dir, "x/y").aiPolicy.stance, "ban");
    rmSync(path.join(dir, "AI_POLICY.md"));
    try { symlinkSync(path.join(outside, "secret.txt"), path.join(dir, "AGENTS.md")); } catch { return; /* no symlink privilege */ }
    const p = detectProfile(dir, "x/y");
    assert.equal(p.agentInstructions, null, "a symlink must not pull host files into the prompt");
    assert.equal(p.aiPolicy.stance, "disclose");
  } finally {
    rmSync(dir, { recursive: true, force: true });
    rmSync(outside, { recursive: true, force: true });
  }
});

test("setupPlan: built-in recipes, detected fallbacks, and a key that follows the lockfile", () => {
  const node = fixture({ "package.json": "{}", "yarn.lock": "a@1\n" });
  const py = fixture({ "pyproject.toml": "[project]\nname='x'\n" });
  const bare = fixture({ "README.md": "hi" });
  try {
    assert.match(setupPlan(bare, "vllm-project/vllm")!.commands.join("\n"), /VLLM_USE_PRECOMPILED=1 uv pip install .* --torch-backend=cpu/);
    assert.equal(setupPlan(bare, "vllm-project/vllm")!.persistent, true);
    assert.match(setupPlan(bare, "react/react")!.commands[0], /^yarn install --frozen-lockfile/);
    assert.equal(setupPlan(bare, "pytorch/pytorch"), null);
    assert.match(setupPlan(node, "x/y")!.commands[0], /^yarn install/);
    assert.equal(setupPlan(py, "x/y")!.persistent, true);
    assert.equal(setupPlan(bare, "x/y"), null);
    const plan = setupPlan(node, "x/y")!;
    const before = setupKey(node, plan);
    assert.match(before, /^[0-9a-f]{12}$/);
    assert.equal(setupKey(node, plan), before, "stable for the same lockfile");
    writeFileSync(path.join(node, "yarn.lock"), "a@2\n");
    assert.notEqual(setupKey(node, plan), before, "a changed lockfile is a new environment");
  } finally {
    for (const d of [node, py, bare]) rmSync(d, { recursive: true, force: true });
  }
});

test("built-in profiles: vllm DCO, react CLA, pytorch scope rules", () => {
  const empty = fixture({ "README.md": "hi" });
  try {
    assert.equal(detectProfile(empty, "vllm-project/vllm").dco, true);
    assert.match(detectProfile(empty, "facebook/react").cla!, /Meta Contributor License Agreement/);
    assert.match(detectProfile(empty, "react/react").cla!, /Meta Contributor License Agreement/, "the repository's new name");
    assert.match(detectProfile(empty, "pytorch/pytorch").cla!, /EasyCLA/);
    assert.equal(detectProfile(empty, "other/repo").dco, false);
  } finally {
    rmSync(empty, { recursive: true, force: true });
  }
  assert.deepEqual(outOfScopePaths("pytorch/pytorch", ["torch/nn/modules/linear.py", "aten/src/ATen/native/Linear.cpp", "torch/csrc/api/x.h"]), ["aten/src/ATen/native/Linear.cpp", "torch/csrc/api/x.h"]);
  assert.deepEqual(outOfScopePaths("vllm-project/vllm", ["csrc/x.cu"]), []);
  assert.match(refuseIssue("pytorch/pytorch", "Wrong result in CUDA kernel", "see aten/src/ATen/native/cuda/foo.cu")!, /C\+\+\/CUDA/);
  assert.equal(refuseIssue("pytorch/pytorch", "torch.nn.Linear repr is wrong", "the __repr__ prints the wrong bias"), null);
  assert.equal(refuseIssue("facebook/react", "crash in foo.cpp", ""), null);
  assert.match(cloneEnv("pytorch/pytorch").OPENSRCER_CLONE_SPARSE, /torch test tools/);
  assert.equal(cloneEnv("facebook/react").OPENSRCER_CLONE_SPARSE, undefined);
});
